"""How crunch_uml identifies itself in what it produces.

Every export says which crunch_uml wrote it, so that a file (or a database)
can be traced back to the version that made it. One place for the wording,
so that all formats say the same thing:

* ``label()``            ``crunch_uml 0.8.8``
* ``generated_by()``     ``Generated by crunch_uml 0.8.8 (https://github.com/brienen/crunch_uml)``
* ``release_iri()``      the GitHub release of this version, for Linked Data
* ``as_dict()``          name, version and url, for JSON documents
* ``version_line()``     label, plus the git commit when run from a checkout, for ``--version`` and the log

The exports carry the version only, never the build or a timestamp: the same
model exported twice by the same release gives the same bytes.
"""

from crunch_uml._version import __version__, producer_build

NAME = "crunch_uml"
HOMEPAGE = "https://github.com/brienen/crunch_uml"

# Key of the generator entry in the JSON export. The underscore keeps it apart
# from the table names; the json parser skips every key that is no table.
JSON_KEY = "_generator"


def label() -> str:
    return f"{NAME} {__version__}"


def generated_by() -> str:
    return f"Generated by {label()} ({HOMEPAGE})"


def release_iri() -> str:
    return f"{HOMEPAGE}/releases/tag/v{__version__}"


def as_dict() -> dict:
    return {"name": NAME, "version": __version__, "url": HOMEPAGE}


def version_line() -> str:
    build = producer_build()
    # 'pypi' means: no git metadata next to the package (an installed release
    # or a source download), so there is no commit to name.
    return label() if build == "pypi" else f"{label()} (git {build[:12]})"
